def compress_runs(values):
    out=[]
    for v in values:
        if out and out[-1][0]==v:
            out[-1][1]+=1
        else:
            out.append([v,1])
    return out

def merge_sorted(left,right):
    out=[]
    i=j=0
    while i<len(left) and j<len(right):
        if left[i]<=right[j]:
            out.append(left[i]); i+=1
        else:
            out.append(right[j]); j+=1
    return out+left[i:]+right[j:]

def unique_once(values):
    counts={}
    for v in values:
        counts[v]=counts.get(v,0)+1
    return [v for v in values if counts[v]==1]

def split_signs(values):
    negative=[]
    other=[]
    for v in values:
        if v<0: negative.append(v)
        else: other.append(v)
    return [negative,other]

def transpose_rect(rows):
    if not rows: return []
    out=[]
    for col in range(len(rows[0])):
        line=[]
        for row in rows: line.append(row[col])
        out.append(line)
    return out

def missing_between(values):
    present=set(values)
    return [x for x in range(min(values)+1,max(values)) if x not in present]

def common_suffix(a,b):
    count=0
    while count<min(len(a),len(b)) and a[-1-count]==b[-1-count]:
        count+=1
    return count

def sum_integer_tokens(text):
    total=0
    for token in text.split():
        digits=token[1:] if token[:1] in ["+","-"] else token
        if digits and all(c in "0123456789" for c in digits): total+=int(token)
    return total

def pair_sums(values):
    out=[]
    for i in range(1,len(values)): out.append(values[i-1]+values[i])
    return out

def stock_after(stock,demand):
    out={}
    for key,value in stock.items(): out[key]=max(0,value-demand.get(key,0))
    return out

def first_peak(values):
    for i in range(1,len(values)-1):
        if values[i]>values[i-1] and values[i]>values[i+1]: return i
    return -1

def balanced_steps(steps):
    balance=0
    for step in steps:
        balance+=step
        if balance<0:return False
    return balance==0

def reverse_blocks(values,k):
    out=[]
    for start in range(0,len(values),k): out.extend(values[start:start+k][::-1])
    return out

def nearest_zero(values):
    best=values[0]
    for v in values[1:]:
        if abs(v)<abs(best) or (abs(v)==abs(best) and v>best):best=v
    return best
